function activeListings(){return typeof visibleSet==='function'?visibleSet({items:listings,search:state.search,predicate:matchFilter,keepUnlocated:true}):listings.filter(matchFilter)}
function distanceLabelHTML(x){if(!state.search||typeof haversineMi!=='function'||typeof formatDistance!=='function'||!Number.isFinite(x.lat)||!Number.isFinite(x.lng))return '';return `<span class="card__distance">${safeListingText(formatDistance(haversineMi(state.search,x)))} mi</span>`}
function geoEmptyState(){if(!state.search||typeof isDefaultArea!=='function'||typeof nextRadius!=='function'||isDefaultArea(state.search))return null;const r=state.search.radius,next=nextRadius(r);const headline=state.search.mode==='device'?`Nothing within ${r} miles of your location yet.`:state.search.mode==='area'?'Nothing in this map area yet.':`Nothing within ${r} miles of ${state.search.zip} yet.`;return {headline,next}}
function wireEmptyAction(geoEmpty,formUrl){const btn=document.getElementById('emptyActionBtn');if(!btn)return;btn.hidden=false;if(geoEmpty.next){btn.textContent=`Expand to ${geoEmpty.next} miles`;btn.onclick=()=>document.dispatchEvent(new CustomEvent('hf:expand-radius',{detail:{radius:geoEmpty.next}}))}else{btn.textContent='Add a listing in your area';btn.onclick=()=>window.open(formUrl,'_blank','noopener')}}
// Radius circle for the current search area, in the site palette.
let searchCircle=null;
let openTonightOK=false;
function syncSearchCircle(){if(typeof L==='undefined'||!map)return;if(searchCircle){map.removeLayer(searchCircle);searchCircle=null}if(!state.search)return;searchCircle=L.circle([state.search.lat,state.search.lng],{radius:state.search.radius*1609.344,color:'#FF7A1A',weight:2,dashArray:'6 6',fillColor:'#FF7A1A',fillOpacity:.05,interactive:false}).addTo(map)}
// 1A Phase F (spec 8.7/9.5): events ON THE ROUTE render as purple skull pins
// on the Displays and Treat stops maps. They track route membership (never the
// count/list logic) and are rebuilt whenever the route changes, since every
// membership change flows through renderCards → syncEventPins.
const eventMarkers=[];
function eventIcon(){const w=pinWidth(),h=pinHeight(w);return L.divIcon({className:'',html:'<div class="pin pin--event"><img class="pin__art" src="assets/icons/pin-event.svg" alt=""></div>',iconSize:[w,h],iconAnchor:[w/2,h]})}
function syncEventPins(){eventMarkers.forEach(m=>map.removeLayer(m));eventMarkers.length=0;if(state.category==='events')return;state.route.filter(r=>r.eventId!=null).forEach(r=>{const ev=events.find(x=>x.id===r.eventId);if(!ev||!Number.isFinite(ev.lat)||!Number.isFinite(ev.lng))return;const m=L.marker([ev.lat,ev.lng],{icon:eventIcon(),keyboard:true,title:`Event: ${ev.name}`,zIndexOffset:900}).addTo(map);m.getElement()?.setAttribute('aria-label',`Event: ${ev.name}`);m.on('click',()=>{if(typeof openEvent==='function')openEvent(ev.id)});eventMarkers.push(m)})}
document.addEventListener('hf:search-changed',e=>{state.search=e.detail;renderCards();renderRoute();renderPeek(state.selected);syncSearchCircle();if(searchCircle){map.fitBounds(searchCircle.getBounds().pad(0.12));setTimeout(()=>map.invalidateSize(),100)}});

const FEATURE_ICONS={
 'Costumes Available':{label:'Costumes Available',path:'M10 5a2 2 0 1 1 3 2l-1 1v3M12 11 2 18v3h20v-3Z'},
 'Music/Sound':{label:'Music / Sound',path:'M9 18V5l11-2v13M9 8l11-2M9 18c0 2-5 3-5 0s5-3 5 0m11-2c0 2-5 3-5 0s5-3 5 0'},
 'Photo Opportunities':{label:'Photo opportunities',path:'M3 7h5l2-3h4l2 3h5v14H3ZM16 14a4 4 0 1 1-8 0 4 4 0 0 1 8 0'},
 'Fog':{label:'Fog',path:'M3 9h18M5 13h14M2 17h20M7 5h10M5 21h14'},
 'Lights':{label:'Lights',path:'M8 16c-6-6-1-13 4-13s10 7 4 13ZM9 20h6M10 23h4M12 1v1M2 8l2 1m16 0 2-1'},
 'Animatronics':{label:'Animatronics',path:'M6 7h12v13H6ZM12 3v4M8 11h1m6 0h1M9 16h6M3 10v6m18-6v6M8 20v3m8-3v3'},
 'Actors':{label:'Live Actors',path:'M3 4l9 2v12c-7 0-9-7-9-14ZM12 6l9-2c0 7-2 14-9 14M6 9h2m8 0h2M7 13l2 1m6 0 2-1'},
 'Spider theme':{label:'Spider theme',path:'M15 13a3 4 0 1 1-6 0 3 4 0 0 1 6 0M12 6v3M9 10 5 7 2 4m13 6 4-3 3-3M9 12H4l-2-2m13 2h5l2-2M9 14l-5 2-2 4m13-6 5 2 2 4M10 16l-3 3v4m7-7 3 3v4'},
 'Spooky Decor':{label:'Spooky decor',path:'M5 21V9a7 7 0 0 1 14 0v12l-4-2-3 2-3-2ZM8 9h1m6 0h1M10 14h4'},
 'Yard Display':{label:'Yard display',path:'M3 21V8l3-4 3 4v13m6 0V8l3-4 3 4v13M3 11h18M3 17h18'}
};
function featureKey(value){const f=String(value).trim().toLowerCase().replace(/\s*\/\s*/g,'/');if(f==='live actors')return 'Actors';return Object.keys(FEATURE_ICONS).find(k=>k.toLowerCase().replace(/\s*\/\s*/g,'/')===f)||value}
function featureIcon(value){const item=FEATURE_ICONS[featureKey(value)];return item?`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${item.path}" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`:''}
function featureChip(value){const key=featureKey(value),item=FEATURE_ICONS[key];return item?`<span class="chip feature-chip">${featureIcon(key)}<span>${safeListingText(item.label)}</span></span>`:`<span class="chip">${safeListingText(value)}</span>`}
function scarePips(levels){const order=['Family Friendly','Spooky','Scary'];return `<span class="pips">${order.map(x=>`<span class="pip ${levels.includes(x)?'is-on':''}"></span>`).join('')}</span>${safeListingText(levels.length?levels.join(' · '):'Not specified')}`}
function listingStatusHTML(x){if(!['temporarily_closed','weather_cancelled'].includes(x.status))return '';if(x.statusUntil&&new Date(x.statusUntil).getTime()<Date.now())return '';return `<div class="listing-status" role="note"><strong>${x.status==='weather_cancelled'?'Weather cancellation':'Temporarily closed'}</strong>${x.statusNote?`<span>${safeListingText(x.statusNote)}</span>`:''}${x.statusUntil?`<small>Through ${safeListingText(new Date(x.statusUntil).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))}</small>`:''}<small>Check the host’s updates before visiting.</small></div>`}
function safeListingText(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function listingUpdatedHTML(x){if(!x.updatedAt)return '';const date=new Date(x.updatedAt+'T12:00:00');if(Number.isNaN(date.getTime()))return '';return `<p class="listing-updated">Listing updated <time datetime="${safeListingText(x.updatedAt)}">${date.toLocaleDateString(undefined,{dateStyle:'medium'})}</time></p>`}
function treatCardHTML(x){const onRoute=state.route.some(r=>r.num===x.num);return `<article class="card card--compact treat-stop-card ${state.selected===x.num?'is-selected':''}${onRoute?' card--on-route':''}" data-card="${x.num}" tabindex="0" aria-label="${safeListingText(x.name)}"><div class="card__head"><div class="card__pin">${pinHTML(x.num,isTreatStop(x)?'treat':'display')}</div><div class="card__heading"><h3 class="card__name"><span class="card__nametext" data-card-name="${x.num}">${safeListingText(x.name)}</span></h3><div class="card__subline"><span class="card__town">${safeListingText(x.town)}</span>${distanceLabelHTML(x)}${typeof openTonightBadgeHTML==='function'?openTonightBadgeHTML(x,{eligible:openTonightOK}):''}</div></div></div>${listingStatusHTML(x)}<a class="card__address" href="${gmapsDirections(x.address)}" target="_blank" rel="noopener" aria-label="Directions to ${safeListingText(x.name)}">${safeListingText(x.address)} ↗</a><p class="card__hours">${safeListingText(listingHoursText(x))}</p><div class="chips">${x.features.map(v=>`<span class="chip">${safeListingText(v)}</span>`).join('')}</div><div class="card__actions"><button class="btn card__route-btn" type="button" data-route="${x.num}" aria-pressed="${onRoute}">${onRoute?'✓ On your route':'+ Add to route'}</button><button class="btn card__fav-btn" type="button" data-fav="${x.num}" aria-pressed="${state.favorites.some(f=>f.num===x.num)}" aria-label="${state.favorites.some(f=>f.num===x.num)?`Remove #${x.num} from favorites`:`Save #${x.num} to favorites`}">${state.favorites.some(f=>f.num===x.num)?'♥':'♡'}</button></div><div class="card__meta"><div class="card__meta-left"><details class="card__notes"><summary>Host notes</summary><div>${safeListingText(x.notes||'No additional notes yet.')}</div></details><button type="button" class="card-rating" data-feedback="${x.num}" data-rating-summary="${x.num}" aria-label="View ratings for ${safeListingText(x.name)}">No ratings yet</button></div><div class="card__meta-right"><button type="button" class="card__metalink" data-report-listing="${x.num}">Report</button><button type="button" class="card__metalink" data-share-house="${x.num}">Share</button></div></div></article>`}
function cardHTML(x){if(x.placeholder)return `<article class="card card--compact card--vacant" aria-label="Listing ${x.num} available"><div class="card__head"><span class="vacant-number">${x.num}</span><div class="card__heading"><h3 class="card__name">Listing number available</h3></div></div><div class="card__body"><p>This number is reserved for the next new listing.</p></div></article>`;if(isTreatStop(x))return treatCardHTML(x);const selected=state.selected===x.num,onRoute=state.route.some(r=>r.num===x.num);return `<article class="card card--compact ${selected?'is-selected':''}${onRoute?' card--on-route':''}" data-card="${x.num}" tabindex="0" aria-label="${safeListingText(x.name)}"><div class="card__head"><div class="card__pin">${pinHTML(x.num,isTreatStop(x)?'treat':'display')}</div><div class="card__heading"><h3 class="card__name"><span class="card__nametext" data-card-name="${x.num}">${safeListingText(x.name)}</span></h3><div class="card__subline"><span class="card__town">${safeListingText(x.town)}</span>${distanceLabelHTML(x)}${typeof openTonightBadgeHTML==='function'?openTonightBadgeHTML(x,{eligible:openTonightOK}):''}</div></div></div>${listingStatusHTML(x)}<a class="card__address" href="${gmapsDirections(x.address)}" target="_blank" rel="noopener" aria-label="Directions to ${safeListingText(x.name)}">${safeListingText(x.address)} ↗</a><p class="card__hours">${safeListingText(listingHoursText(x))}</p><p class="card__scare-row"><span class="card__scare">${scarePips(x.levels)}</span></p><div class="card__tags">${x.type.map(t=>`<span class="chip chip--type">${safeListingText(t)}</span>`).join('')}<div class="chips">${x.features.map(featureChip).join('')}</div></div><div class="card__actions"><button class="btn card__route-btn" type="button" data-route="${x.num}" aria-pressed="${onRoute}">${onRoute?'✓ On your route':'+ Add to route'}</button><button class="btn card__fav-btn" type="button" data-fav="${x.num}" aria-pressed="${state.favorites.some(f=>f.num===x.num)}" aria-label="${state.favorites.some(f=>f.num===x.num)?`Remove #${x.num} from favorites`:`Save #${x.num} to favorites`}">${state.favorites.some(f=>f.num===x.num)?'♥':'♡'}</button></div><div class="card__meta"><div class="card__meta-left"><details class="card__notes"><summary>Host notes</summary><div>${safeListingText(x.notes||'No additional notes yet.')}</div></details><button type="button" class="card-rating" data-feedback="${x.num}" data-rating-summary="${x.num}" aria-label="View ratings for ${safeListingText(x.name)}">No ratings yet</button></div><div class="card__meta-right"><button type="button" class="card__metalink" data-report-listing="${x.num}">Report</button><button type="button" class="card__metalink" data-share-house="${x.num}">Share</button></div></div></article>`}

function dateFilterChipsHTML(){
 const f=state.dateFilter||{};
 const chip=(kind,label)=>`<button type="button" class="filter filter--date" data-date-filter="${kind}" aria-pressed="${f.kind===kind}">${label}</button>`;
 const dateInput=f.kind==='date'?`<input type="date" id="dateFilterInput" class="filter-date-input" value="${safeListingText(f.date||'')}" aria-label="Choose a date">`:'';
 return `<div class="filter-tier filter-tier--date"><span class="filterbar__label">When</span>${chip('tonight','Tonight')}${chip('weekend','This weekend')}${chip('date','Choose a date')}${dateInput}</div>`;
}
function renderFilters(){const button=f=>`<button class="filter ${FEATURE_ICONS[f]?'filter--feature':''}" type="button" data-filter="${f}" aria-pressed="${state.filter===f}">${featureIcon(f)}${safeListingText(FEATURE_ICONS[f]?.label||f)}</button>`;const featureActive=filters.some(f=>FEATURE_ICONS[f]&&state.filter===f),anyActive=state.filter!=='All'||Boolean(state.dateFilter&&state.dateFilter.kind);document.getElementById('filters').innerHTML=`<div class="filter-tier filter-tier--primary"><span class="filterbar__label">Show</span>${filters.filter(f=>!FEATURE_ICONS[f]).map(button).join('')}${anyActive?'<button class="filter filter--reset" type="button" data-reset-filters>Reset filters</button>':''}</div><details class="filter-tier filter-tier--features"${featureActive?' open':''}><summary>Features</summary>${filters.filter(f=>FEATURE_ICONS[f]).map(button).join('')}</details>${dateFilterChipsHTML()}`}

function syncListingMarkers(visible){if(typeof L==='undefined'||!map||!markerByNum)return;const keep=new Set(visible.filter(x=>!x.placeholder&&Number.isFinite(x.lat)&&Number.isFinite(x.lng)).map(x=>x.num));markerByNum.forEach((m,n)=>{const on=map.hasLayer(m);if(keep.has(n)){if(!on)m.addTo(map)}else if(on)map.removeLayer(m)})}
function renderCards(){const visible=activeListings();openTonightOK=typeof openTonightEligible==='function'&&typeof todayParts==='function'?openTonightEligible(visible,todayParts().dateStr):false;const geoEmpty=typeof geoEmptyState==='function'?geoEmptyState():null,noResults=document.getElementById('noResults'),nonPlaceholder=visible.filter(x=>!x.placeholder);noResults.dataset.mode=(!visible.length&&geoEmpty)?'geo':'';const noun=state.category==='treats'?'treat stop':'display',dateLabel=typeof dateFilterLabel==='function'?dateFilterLabel(state.dateFilter):null;document.getElementById('countLine').textContent=(state.search?`${nonPlaceholder.length} ${noun}${nonPlaceholder.length===1?'':'s'} within ${state.search.radius} mi`:`${nonPlaceholder.length} ${noun}${visible.length===1?'':'s'} shown`)+(state.filter!=='All'?' · '+state.filter:'')+(dateLabel?' · '+dateLabel:'');document.getElementById('cardList').innerHTML=visible.map(cardHTML).join('');syncListingMarkers(visible);noResults.classList.toggle('is-hidden',visible.length>0);const actionBtn=document.getElementById('emptyActionBtn');if(!visible.length&&geoEmpty){noResults.querySelector('strong').textContent=geoEmpty.headline;document.getElementById('noResultsText').textContent='';wireEmptyAction(geoEmpty,state.category==='treats'?TREAT_FORM_URL:FORM_URL)}else{document.getElementById('noResultsText').textContent=`No displays match “${state.filter}” right now.`;if(actionBtn)actionBtn.hidden=true}const te=document.getElementById('treatEmpty');if(te){const showTe=state.category==='treats'&&!visible.length&&!geoEmpty;te.classList.toggle('is-hidden',!showTe);if(showTe){te.innerHTML=`<img class="treat-empty__icon" src="assets/icons/pin-treat-stop.svg" alt="" width="40" height="47"><h3 class="treat-empty__title">No treat stops listed within ${state.search?state.search.radius:25} mi yet</h3><p class="treat-empty__body">Handing out candy on Halloween? Add your home so trick-or-treaters can find you.</p><div class="treat-empty__actions"><button type="button" class="btn btn--route" data-treat-add>Add your home as a treat stop</button><button type="button" class="btn btn--outline" data-try-radius="50">Try 50 mi</button></div>`;te.querySelector('[data-treat-add]').onclick=()=>window.open(TREAT_FORM_URL,'_blank','noopener');te.querySelector('[data-try-radius]').onclick=()=>document.dispatchEvent(new CustomEvent('hf:expand-radius',{detail:{radius:50}}))}}markerByNum.forEach((m,n)=>{const x=listings.find(v=>v.num===n);if(x&&matchFilter(x))m.addTo(map);else map.removeLayer(m)});syncEventPins();wireCards()}
function wireCards(){document.querySelectorAll('[data-card]').forEach(card=>{const n=+card.dataset.card;card.addEventListener('click',e=>{if(e.target.closest('button,a,details'))return;selectListing(n,true)});card.addEventListener('keydown',e=>{if(e.target!==card||!['Enter',' '].includes(e.key))return;e.preventDefault();selectListing(n,true)});card.addEventListener('mouseenter',()=>linkPair(n,true));card.addEventListener('mouseleave',()=>linkPair(n,false));card.addEventListener('focus',()=>linkPair(n,true));card.addEventListener('blur',()=>linkPair(n,false))});document.querySelectorAll('[data-route]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleRoute(+b.dataset.route)});document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleFavorite(+b.dataset.fav)})}
function linkPair(n,on){if(matchMedia('(pointer:fine)').matches){document.querySelector(`[data-card="${n}"]`)?.classList.toggle('is-linked',on);markerByNum.get(n)?.getElement()?.querySelector('.pin')?.classList.toggle('is-linked',on)}}
function selectListing(n,scroll=false){if(listings.find(x=>x.num===n)?.placeholder)return;state.selected=n;markerByNum.forEach((m,num)=>m.getElement()?.querySelector('.pin')?.classList.toggle('is-selected',num===n));document.querySelectorAll('[data-card]').forEach(c=>c.classList.toggle('is-selected',+c.dataset.card===n));renderPeek(n);if(scroll&&innerWidth<1024){const card=document.querySelector(`[data-card="${n}"]`);if(!card)return;const panel=card.closest('.list-column');if(panel&&panel.scrollHeight>panel.clientHeight)panel.scrollTo({top:card.offsetTop-panel.offsetTop-Math.max(0,(panel.clientHeight-card.offsetHeight)/2),behavior:'smooth'});else window.scrollTo({top:card.getBoundingClientRect().top+window.scrollY-Math.max(0,(innerHeight-card.offsetHeight)/2),behavior:'smooth'})}}
// K4 map popup (spec 8.7): one 280px popup at a time inside #mapPeek — photo
// slot (filled by loadPeekPhotos when photos exist), name, town · distance ·
// ★ rating, full-width add-to-route, × close.
function hidePeek(){document.getElementById('mapPeek').classList.add('is-hidden')}
function renderPeek(n){const x=listings.find(v=>v.num===n),peek=document.getElementById('mapPeek');if(!x||x.placeholder||!matchFilter(x)){hidePeek();return}const onRoute=state.route.some(r=>r.num===n),dist=state.search&&typeof haversineMi==='function'&&typeof formatDistance==='function'&&Number.isFinite(x.lat)&&Number.isFinite(x.lng)?formatDistance(haversineMi(state.search,x))+' mi':'',rating=typeof ratingSummaries!=='undefined'?ratingSummaries.get(n):null,meta=[x.town,dist].filter(Boolean).join(' · ')+(rating&&rating.count?` · ★ ${rating.average}`:'');peek.innerHTML=`<div class="map-popup" role="dialog" aria-label="${safeListingText(x.name)}"><button class="map-popup__close" type="button" aria-label="Close">×</button><div class="map-popup__photo" data-peek-photo></div><div class="map-popup__body"><h3 class="map-popup__name">${safeListingText(x.name)}</h3><p class="map-popup__meta">${safeListingText(meta)}</p><button class="btn btn--route map-popup__add" type="button" data-peek-route="${n}" aria-pressed="${onRoute}">${onRoute?'✓ On your route':'+ Add to route'}</button></div></div>`;peek.classList.remove('is-hidden');typeof loadPeekPhotos==='function'&&loadPeekPhotos(n,x);peek.querySelector('.map-popup__close').onclick=hidePeek;peek.querySelector('[data-peek-route]').onclick=()=>toggleRoute(n)}
function toggleRoute(n){const listing=listings.find(x=>x.num===n);if(!listing||listing.placeholder)return;if(!state.route.some(r=>r.num===n)&&state.route.length>=10){state.routeMessage='Routes can have up to 10 stops.';renderRoute();return}state.routeMessage='';const had=state.route.length;state.route=state.route.some(r=>r.num===n)?state.route.filter(r=>r.num!==n):[...state.route,{num:n,entityId:listing.entityId}];if(state.route.length>had)setRouteExpanded(true,false);try{localStorage.setItem('hfroute:2026',JSON.stringify(state.route))}catch{}renderCards();renderRoute();renderPeek(state.selected);markerByNum.forEach((m,num)=>m.getElement()?.querySelector('.pin')?.classList.toggle('is-on-route',state.route.some(r=>r.num===num)))}
// v5 Phase F: events join the shared route with a discriminated {eventId}
// entry (see routing.js). Same toggle pattern as listings; no map pins for
// events, so only the planner and cards re-render.
function toggleEventRoute(eventId){const ev=events.find(x=>x.id===eventId);if(!ev)return;if(!state.route.some(r=>r.eventId===eventId)&&state.route.length>=10){state.routeMessage='Routes can have up to 10 stops.';renderRoute();return}state.routeMessage='';const had=state.route.length;state.route=toggleRouteEntry(state.route,{eventId:ev.id});if(state.route.length>had)setRouteExpanded(true,false);try{localStorage.setItem('hfroute:2026',JSON.stringify(state.route))}catch{}renderRoute();renderCards()}

function toggleFavorite(n){const listing=listings.find(x=>x.num===n);if(!listing||listing.placeholder)return;state.favorites=toggleFavoriteEntry(state.favorites,n,listing.entityId);try{localStorage.setItem('hffavs:v1',JSON.stringify(state.favorites))}catch{}renderCards();renderPeek(state.selected)}
let routeExpanded=false;
let routeStartEditing=false;
function setRouteExpanded(open,focus){routeExpanded=open;const t=document.getElementById('routeToggle'),r=document.getElementById('routeRegion');if(!t||!r)return;t.setAttribute('aria-expanded',String(open));r.hidden=!open;const hint=document.getElementById('routeToggleHint');if(hint)hint.textContent=open?'Hide ▾':'Expand ▴';if(focus){if(open){const f=r.querySelector('button,input');f&&f.focus()}else t.focus()}}
function openRouteSheet(){renderRoute();const s=document.getElementById('routeSheet');if(s&&typeof s.showModal==='function')s.showModal()}
document.getElementById('routeToggle').onclick=()=>setRouteExpanded(!routeExpanded,true);
function routeStartLabel(){if(state.startMode==='address'&&state.startAddr.trim())return state.startAddr.trim();if(typeof describeSearch==='function'&&state.search)return describeSearch(state.search);return 'your location'}
function reorderRouteStop(fromKey,toKey){if(!fromKey||fromKey===toKey)return;const from=state.route.findIndex(r=>routeEntryKey(r)===fromKey),to=state.route.findIndex(r=>routeEntryKey(r)===toKey);if(from<0||to<0)return;const [moved]=state.route.splice(from,1);state.route.splice(to,0,moved);state.routeMessage='Stop order updated.';try{localStorage.setItem('hfroute:2026',JSON.stringify(state.route))}catch{}renderRoute()}
function suggestOrder(){if(state.route.length<2)return;const origin=state.startCoords||(state.search&&Number.isFinite(state.search.lat)&&Number.isFinite(state.search.lng)?{lat:state.search.lat,lng:state.search.lng}:null);state.route=suggestRouteOrder(state.route,listings,events,origin);state.routeMessage='Suggested nearest-first from your starting point. Event times stay in order. Check roads and hours in Google Maps.';try{localStorage.setItem('hfroute:2026',JSON.stringify(state.route))}catch{}renderRoute()}
function renderRoute(){const sheetBadge=document.getElementById('routeSheetBadge');if(sheetBadge)sheetBadge.textContent=`${state.route.length} stop${state.route.length===1?'':'s'}`;document.getElementById('mobileRouteBar').classList.toggle('is-hidden',!state.route.length);document.getElementById('mobileMapRouteBtn').disabled=!state.route.length;document.getElementById('mobileRouteCount').textContent=`${state.route.length} stop${state.route.length===1?'':'s'}`;const present=state.route.map(r=>r.eventId!=null?{...events.find(x=>x.id===r.eventId),isEvent:true}:listings.find(x=>x.num===r.num)).filter(Boolean);const flagByNum=new Map();if(typeof stopsWithAreaFlags==='function')stopsWithAreaFlags(present.filter(s=>!s.isEvent),state.search).forEach(s=>flagByNum.set(s.num,s.outOfArea));const stops=present.map(s=>s.isEvent?{...s,outOfArea:false}:{...s,outOfArea:Boolean(flagByNum.get(s.num))});const subline=s=>{if(s.isEvent){const d=s.date||String(s.startAt||'').slice(0,10),dateLine=s.ongoing?'Open all season':(d?new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}):'Date TBA');return dateLine+(s.hours?' · '+s.hours:'')+(s.town?' · '+s.town:'')}const parts=[s.town];if(state.search&&typeof haversineMi==='function'&&typeof formatDistance==='function'&&Number.isFinite(s.lat)&&Number.isFinite(s.lng))parts.push(formatDistance(haversineMi(state.search,s))+' mi');if(s.times)parts.push(compactTime(s.times));else if(s.dates)parts.push(s.dates);return parts.filter(Boolean).join(' · ')};const planner=document.getElementById('routePlanner'),sheetBody=document.getElementById('routeSheetBody'),plannerTargets=[planner,sheetBody].filter(Boolean),html=`<div class="route__start"><div class="route__start-summary"><span class="route__start-label">Starting from</span><strong class="route__start-loc">${safeListingText(routeStartLabel())}</strong><button type="button" class="route__linkbtn route__change" data-start-edit>Change</button></div><div class="route__start-edit"${routeStartEditing?'':' hidden'}><div class="route__label">Starting point</div><div class="route__start-row"><input class="route__input" id="startAddr" value="${safeListingText(state.startAddr||routeStartLabel())}" placeholder="Enter your starting address"><button type="button" class="route__locate" data-locate aria-label="Use my current location">◎</button></div><div class="seg" role="radiogroup" aria-label="Starting point"><button type="button" data-mode="current" aria-checked="${state.startMode==='current'}">My location</button><button type="button" data-mode="address" aria-checked="${state.startMode==='address'}">Enter address</button></div>${state.startMode==='current'?`<div class="current-note"><span class="current-dot"></span>Google Maps uses your location when you open directions</div>`:''}</div></div><div class="route__stops">${stops.length?`<ol class="route__timeline">${stops.map((s,i)=>`<li class="route-stop" draggable="true" data-stop-key="${s.isEvent?'e:'+s.id:'n:'+s.num}"><span class="route-stop__grip" aria-hidden="true"></span><span class="route-stop__num" aria-hidden="true">${i+1}</span><img class="route-stop__icon" src="assets/icons/${s.isEvent?'pin-event':'pin-display'}.svg" alt="" width="30" height="35"><div class="route-stop__meta"><strong>${safeListingText(s.name)}</strong><small>${safeListingText(subline(s))}${s.outOfArea?' · Outside your current search area':''}</small></div><div class="route-stop__controls"><button type="button" data-move-stop="${s.isEvent?'e:'+s.id:'n:'+s.num}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move ${safeListingText(s.name)} earlier">↑</button><button type="button" data-move-stop="${s.isEvent?'e:'+s.id:'n:'+s.num}" data-direction="1" ${i===stops.length-1?'disabled':''} aria-label="Move ${safeListingText(s.name)} later">↓</button></div><button type="button" class="route-stop__remove route__linkbtn" data-remove="${s.isEvent?'e:'+s.id:'n:'+s.num}" aria-label="Remove ${safeListingText(s.name)}"><span class="route-stop__remove-label">Remove</span><span class="route-stop__remove-x" aria-hidden="true">×</span></button></li>`).join('')}</ol>`:`<div class="empty"><strong>No stops yet</strong><span>Add a display, treat stop, or event to start planning your route.</span></div>`}</div><div class="route__foot"><p class="route__status" id="routeOrderStatus" role="status">${safeListingText(state.routeMessage||'')}</p><p class="route__helper route__foot-helper">Up to 10 stops. Drag to reorder.</p><div class="route__foot-row"><button class="btn btn--primary route__directions" id="mapRouteBtn" type="button" aria-disabled="${stops.length===0}"><span class="route__dir-panel">Get directions ↗</span><span class="route__dir-sheet">Directions for this route ↗</span></button><div class="route__links"><button type="button" class="route__linkbtn" id="optimizeRouteBtn" ${stops.length<2?'disabled':''}>Suggest order</button><button type="button" class="route__linkbtn" id="shareOutingBtn" ${stops.length?'':'disabled'}>Share outing</button>${state.category==='events'?'<button type="button" class="route__linkbtn" data-nearby-displays>Displays nearby →</button>':''}</div></div></div>`;plannerTargets.forEach(planner=>{planner.innerHTML=html;planner.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.startMode=b.dataset.mode;state.startCoords=null;state.routeMessage='';renderRoute()});planner.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const v=b.dataset.remove;if(v.startsWith('e:')){state.routeMessage='';toggleEventRoute(v.slice(2))}else{state.routeMessage='';toggleRoute(+v)}});planner.querySelectorAll('[data-move-stop]').forEach(b=>b.onclick=()=>moveRouteStop(b.dataset.moveStop,+b.dataset.direction));planner.querySelectorAll('[data-start-edit]').forEach(b=>b.onclick=()=>{routeStartEditing=!routeStartEditing;renderRoute()});planner.querySelectorAll('[data-locate]').forEach(b=>b.onclick=()=>{state.startMode='current';state.startCoords=null;state.routeMessage='';renderRoute()});planner.querySelectorAll('[data-nearby-displays]').forEach(b=>b.onclick=()=>{const tab=document.getElementById('displaysTab');if(tab)tab.click()});planner.querySelectorAll('.route-stop').forEach(li=>{li.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',li.dataset.stopKey);e.dataTransfer.effectAllowed='move'});li.addEventListener('dragover',e=>{e.preventDefault();li.classList.add('is-dragover')});li.addEventListener('dragleave',()=>li.classList.remove('is-dragover'));li.addEventListener('drop',e=>{e.preventDefault();li.classList.remove('is-dragover');reorderRouteStop(e.dataTransfer.getData('text/plain'),li.dataset.stopKey)})});planner.querySelector('#startAddr')?.addEventListener('input',e=>{state.startAddr=e.target.value;state.startMode='address';state.startCoords=null;state.routeMessage=''});planner.querySelector('#mapRouteBtn').onclick=buildRoute;planner.querySelector('#optimizeRouteBtn').onclick=suggestOrder;planner.querySelector('#shareOutingBtn').onclick=shareOuting})}
async function shareOuting(){if(!state.route.length)return;const link=routeLink(state.route);try{await navigator.clipboard.writeText(link);state.routeMessage='Route link copied — send it to friends.'}catch(e){state.routeMessage='Copy this link: '+link}renderRoute()}

function buildRoute(){const stops=state.route.map(r=>r.eventId!=null?events.find(x=>x.id===r.eventId):listings.find(x=>x.num===r.num)).filter(Boolean);if(!stops.length)return;if(stops.length>10){state.routeMessage='Routes can have up to 10 stops.';renderRoute();return}const capped=stops.slice(0,10),last=capped.at(-1),wps=capped.slice(0,-1).map(x=>x.address).join('|');const p=new URLSearchParams({api:'1',travelmode:'driving',destination:last.address});if(wps)p.set('waypoints',wps);if(state.startMode==='address'&&state.startAddr.trim())p.set('origin',state.startAddr.trim());else if(state.startCoords)p.set('origin',state.startCoords.lat+','+state.startCoords.lng);window.open(`https://www.google.com/maps/dir/?${p.toString()}`,'_blank','noopener')}

async function loadMarkers(){const bounds=[];for(const x of listings){if(x.placeholder||!Number.isFinite(x.lat)||!Number.isFinite(x.lng))continue;const c={lat:x.lat,lng:x.lng};state.coords[x.num]=c;const m=L.marker([c.lat,c.lng],{icon:iconFor(x.num,isTreatStop(x)?'treat':'display'),keyboard:true,title:`${isTreatStop(x)?'Treat stop':'Display'} ${x.num}: ${x.name}`,zIndexOffset:(listings.filter(v=>v.address===x.address).length>1?1000:100)+x.num}).addTo(map);m.getElement()?.setAttribute('aria-label',`${isTreatStop(x)?'Treat stop':'Display'} ${x.num}: ${x.name}`);m.on('click',()=>{selectListing(x.num,true)});m.on('mouseover',()=>linkPair(x.num,true));m.on('mouseout',()=>linkPair(x.num,false));markerByNum.set(x.num,m);bounds.push([c.lat,c.lng])}if(bounds.length)map.fitBounds(bounds,{paddingTopLeft:[40,80],paddingBottomRight:[40,40]});setTimeout(()=>map.invalidateSize(),100)}

document.getElementById('filters').addEventListener('click',e=>{if(e.target.closest('[data-reset-filters]')){state.filter='All';state.dateFilter=typeof saveDateFilter==='function'?saveDateFilter({kind:null,date:null},localStorage):null;renderFilters();renderCards();return}const b=e.target.closest('[data-filter]');if(!b)return;state.filter=state.filter===b.dataset.filter?'All':b.dataset.filter;renderFilters();renderCards()});document.getElementById('showAllBtn').onclick=()=>{state.filter='All';state.features=[];state.dateFilter=typeof saveDateFilter==='function'?saveDateFilter({kind:null,date:null},localStorage):null;renderFilters();renderCards()};document.getElementById('shareBtn').onclick=async()=>{const b=document.getElementById('shareBtn'),payload={title:'Hauntfinder',text:'Find Halloween displays, treat stops, and events near you.',url:'https://hauntfinder.vercel.app/'};try{if(navigator.share)await navigator.share(payload);else{await navigator.clipboard.writeText('https://hauntfinder.vercel.app/');b.textContent='Link copied';setTimeout(()=>b.textContent='Share this site',2000)}}catch{}};
renderFilters();renderCards();renderRoute();loadMarkers();


